const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data=[],readings=[],selected=-1,gas='co2',fileName='',map,layer;
const defs=[['id','Reading ID','text'],['site','Site / collar','text'],['project','Project','text'],['start','Closure start (file local time)','text'],['end','Closure end (file local time)','text'],['mixing','Exclude initial seconds','number'],['temperature','Chamber air (°C)','number'],['pressure','Absolute pressure (kPa)','number'],['chamber','Chamber headspace (L)','number'],['collar','Exposed collar headspace (L)','number'],['loop','Tubing / loop volume (L)','number'],['area','Soil surface area (m²)','number'],['latitude','Latitude (decimal degrees)','number'],['longitude','Longitude (decimal degrees)','number']];
$('fields').innerHTML=defs.map(([k,l,t])=>`<label>${l}<input id="f_${k}" type="${t}" step="any" ${k==='start'||k==='end'?'placeholder="YYYY-MM-DD HH:mm:ss"':''}></label>`).join('');
function save(){try{localStorage.setItem('fieldflux-v1',JSON.stringify({data,readings,selected,fileName}));}catch(e){$('status').textContent='Browser storage is full. Export your results before closing.'}}
function stamp(s){return Date.parse(String(s).trim().replace(' ','T')+'Z')/1000} // nominal file-local times; never use browser timezone
function parseGas(text){const lines=text.replace(/\r/g,'').split('\n');const hi=lines.findIndex(l=>l.startsWith('DATAH\t'));if(hi<0)throw Error('Expected LI-COR DATAH tab-delimited header.');const heads=lines[hi].split('\t'),i=k=>heads.indexOf(k);for(const k of ['CO2','CH4','DATE','TIME'])if(i(k)<0)throw Error('Missing column '+k);const units=lines[hi+1].split('\t');if(units[i('CO2')]!=='ppm'||units[i('CH4')]!=='ppb')throw Error('Expected CO2 in ppm and CH4 in ppb.');return lines.slice(hi+2).filter(l=>l.startsWith('DATA\t')).map(l=>{const a=l.split('\t'),label=a[i('DATE')]+' '+a[i('TIME')];return{t:stamp(label),label,co2:Number(a[i('CO2')]),ch4:Number(a[i('CH4')]),diag:a[i('DIAG')]}}).filter(r=>Number.isFinite(r.t)).map(r=>({...r,co2:Number.isFinite(r.co2)?r.co2:null,ch4:Number.isFinite(r.ch4)?r.ch4:null}));}
function fit(points,g){const p=points.filter(x=>Number.isFinite(x[g]));if(p.length<3)return null;const t0=p[0].t;let mx=0,my=0;for(const r of p){mx+=r.t-t0;my+=r[g]}mx/=p.length;my/=p.length;let xx=0,xy=0,yy=0;for(const r of p){let x=r.t-t0-mx,y=r[g]-my;xx+=x*x;xy+=x*y;yy+=y*y}if(xx===0)return null;const slope=xy/xx;return{slope,intercept:my-slope*mx,t0,r2:yy?xy*xy/(xx*yy):null,n:p.length,min:p[0].t,max:p.at(-1).t};}
function evaluate(r){const a=stamp(r.start),b=stamp(r.end),mix=Number(r.mixing);let errors=[];if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)errors.push('Enter a valid closure start and end.');if(!Number.isFinite(mix)||mix<0||a+mix>=b)errors.push('Mixing exclusion must fit inside the closure.');for(const k of ['temperature','pressure','chamber','collar','loop','area'])if(r[k]===''||r[k]==null||!Number.isFinite(Number(r[k])))errors.push('Missing '+k+'.');if(Number(r.temperature)<=-273.15||Number(r.pressure)<=0||Number(r.area)<=0||Number(r.chamber)<=0||Number(r.collar)<0||Number(r.loop)<0)errors.push('Check positive pressure, chamber volume, soil area and nonnegative extra volumes.');const p=data.filter(x=>x.t>=a+mix&&x.t<=b),c=fit(p,'co2'),h=fit(p,'ch4');if(!c||!h)errors.push('At least three valid concentrations for each gas are required.');let v=(+r.chamber + +r.collar + +r.loop)/1000;const factor=+r.pressure*1000*v/(8.314462618*(+r.temperature+273.15)*+r.area);return{errors,p,c,h,co2:errors.length?null:c.slope*factor,ch4:errors.length?null:h.slope*factor,v};}
const num=n=>n==null||!Number.isFinite(n)?'—':Math.abs(n)<.001&&n!==0?n.toExponential(3):n.toFixed(3);
function current(){return readings[selected]}
function populate(){const r=current();for(const[k]of defs)$('f_'+k).value=r?.[k]??'';render()}
function newReading(){let n=readings.length+1;while(readings.some(r=>r.id==='R'+String(n).padStart(3,'0')))n++;readings.push({id:'R'+String(n).padStart(3,'0'),site:'',project:'Field campaign',start:data[0]?.label||'',end:data.at(-1)?.label||'',mixing:0,temperature:'',pressure:'',chamber:'',collar:0,loop:0,area:'',latitude:'',longitude:''});selected=readings.length-1;populate();save()}
function chart(){const r=current();if(!r||!data.length)return;const e=evaluate(r),a=stamp(r.start),b=stamp(r.end),points=data.filter(x=>x.t>=a&&x.t<=b&&Number.isFinite(x[gas]));if(points.length<2){$('chart').innerHTML='<text x="300" y="120" text-anchor="middle" fill="#79877d">No valid data in this interval</text>';return}const lo=Math.min(...points.map(p=>p[gas])),hi=Math.max(...points.map(p=>p[gas])),span=hi-lo||1,x=t=>55+(t-a)/(b-a)*525,y=v=>195-(v-lo)/span*155;let html='';for(let i=0;i<5;i++){let v=lo+i*span/4;html+=`<line x1="55" x2="580" y1="${y(v)}" y2="${y(v)}" stroke="#e7ebe3"/><text x="45" y="${y(v)+4}" text-anchor="end" font-size="10" fill="#79877d">${v.toFixed(1)}</text>`}const skip=Math.max(1,Math.floor(points.length/1000));html+=`<polyline fill="none" stroke="${gas==='co2'?'#52754a':'#b48447'}" stroke-width="1.8" points="${points.filter((_,i)=>i%skip===0).map(p=>x(p.t)+','+y(p[gas])).join(' ')}"/>`;const f=gas==='co2'?e.c:e.h;if(f)html+=`<line x1="${x(f.min)}" x2="${x(f.max)}" y1="${y(f.intercept+f.slope*(f.min-f.t0))}" y2="${y(f.intercept+f.slope*(f.max-f.t0))}" stroke="#283b35" stroke-dasharray="5 4"/>`;for(let i=0;i<5;i++)html+=`<text x="${55+525*i/4}" y="218" text-anchor="middle" font-size="10" fill="#79877d">${Math.round((b-a)*i/4)} s</text>`;html+=`<text x="55" y="17" fill="#79877d" font-size="11">${gas==='co2'?'CO₂ · ppm':'CH₄ · ppb'}</text>`;$('chart').innerHTML=html;$('chartSub').textContent=`${r.id} · ${points.length.toLocaleString()} valid ${gas.toUpperCase()} samples`;}
function filtered(){return readings.filter(r=>!$('projectFilter').value||r.project===$('projectFilter').value)}
function render(){const r=current(),e=r?evaluate(r):null;$('co2Stat').textContent=num(e?.co2);$('ch4Stat').textContent=num(e?.ch4);$('fitStat').textContent=e?num(e.c?.r2)+' / '+num(e.h?.r2):'—';$('countStat').textContent=readings.length;$('sampleStat').textContent=data.length?data.length.toLocaleString()+' recorded samples':'Awaiting a recording';$('projectTitle').textContent=r?.project||'Untitled field campaign';$('validation').textContent=e?(e.errors.length?e.errors.join(' '):`Effective volume ${(e.v*1000).toFixed(3)} L. Linear fit uses ${e.c.n} CO₂ and ${e.h.n} CH₄ samples. Review the trace before reporting.`):'Add a reading to begin.';let val=$('projectFilter').value;$('projectFilter').innerHTML='<option value="">All projects</option>'+[...new Set(readings.map(x=>x.project))].map(p=>`<option>${esc(p)}</option>`).join('');$('projectFilter').value=val;$('rows').innerHTML=filtered().map(r=>{let e=evaluate(r),i=readings.indexOf(r);let quality=e.errors.length?'Needs inputs':e.c.r2===null||e.h.r2===null?'Constant signal':Math.min(e.c.r2,e.h.r2)<.9?'Review fit':'Fit ≥ 0.90';return `<tr data-id="${i}" class="${i===selected?'selected':''}"><td><strong>${esc(r.id)}</strong><br><span class="muted">${esc(r.site||'Unassigned site')}</span></td><td>${esc(r.project)}</td><td>${esc(r.start)}<br>${esc(r.end)}</td><td>${num(e.co2)}</td><td>${num(e.ch4)}</td><td><span class="pill">${quality}</span></td><td>${hasGPS(r)?'◎ Located':'—'}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No readings in this project.</td></tr>';$('rows').querySelectorAll('tr[data-id]').forEach(row=>row.onclick=()=>{selected=+row.dataset.id;populate()});chart();drawMap()}
function hasGPS(r){return r.latitude!==''&&r.longitude!==''&&r.latitude!=null&&r.longitude!=null&&Number.isFinite(+r.latitude)&&Number.isFinite(+r.longitude)&&Math.abs(+r.latitude)<=90&&Math.abs(+r.longitude)<=180}
function drawMap(){if(!window.L)return;if(!map){map=L.map('map',{scrollWheelZoom:false}).setView([0,10],2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);layer=L.layerGroup().addTo(map)}layer.clearLayers();const g=$('mapGas').value,p=filtered().map(r=>({r,f:evaluate(r)[g]})).filter(x=>hasGPS(x.r)&&Number.isFinite(x.f)),max=Math.max(...p.map(x=>Math.abs(x.f)),1e-12);for(const{r,f}of p)L.circleMarker([+r.latitude,+r.longitude],{radius:7+16*Math.sqrt(Math.abs(f)/max),color:f<0?'#3c7d99':'#b47f38',fillColor:f<0?'#3c7d99':'#b47f38',fillOpacity:.6,weight:1}).addTo(layer).bindPopup(`<strong>${esc(r.id)} · ${esc(r.site)}</strong><br>${num(f)} ${g==='co2'?'µmol':'nmol'} m⁻² s⁻¹`);if(p.length)map.fitBounds(p.map(x=>[+x.r.latitude,+x.r.longitude]),{padding:[40,40],maxZoom:16});$('mapNote').textContent=`${p.length} calculated, located reading(s). Blue = uptake · ochre = emission. Point intensity is relative to the selected gas and project; no spatial interpolation is applied.`}
async function loadGas(text,name){const parsed=parseGas(text);if(!parsed.length)throw Error('No data records found.');if(data.length&&!confirm('Replace the current recording? Existing reading intervals and results will be cleared.'))return;data=parsed;readings=[];selected=-1;fileName=name;newReading();$('status').textContent=`${name} · ${data.length.toLocaleString()} samples · file-local timestamps. Set a closure interval before calculating.`;save()}
function download(name,text,type='text/csv'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
$('template').onclick=()=>download('fieldflux-metadata-template.csv',defs.map(x=>x[0]).join(',')+'\nR001,Collar-01,Project-A,2026-10-12 16:00:00,2026-10-12 16:03:00,20,,,,0,0,,,\n');
$('export').onclick=()=>{const keys=defs.map(x=>x[0]);const extra=['source_file','co2_flux_umol_m2_s','ch4_flux_nmol_m2_s','co2_r2','ch4_r2','co2_slope_ppm_s','ch4_slope_ppb_s','effective_volume_L','quality_notes'];download('fieldflux-results.csv',[keys.concat(extra).join(','),...filtered().map(r=>{const e=evaluate(r);return keys.map(k=>r[k]).concat([fileName,e.co2,e.ch4,e.c?.r2,e.h?.r2,e.c?.slope,e.h?.slope,e.v*1000,e.errors.join(' ')||'Review fit and instrument diagnostics']).map(csvCell).join(',')})].join('\n'))};
$('calculate').onclick=()=>{if(!current()){newReading();return}const r={};for(const[k,,t]of defs){const value=$('f_'+k).value.trim();r[k]=t==='number'&&value!==''?Number(value):value}if(!r.id||readings.some((x,i)=>i!==selected&&x.id===r.id)){alert('Use a unique, nonempty reading ID.');return}readings[selected]=r;save();render()};$('new').onclick=newReading;$('remove').onclick=()=>{if(selected<0)return;if(!confirm('Delete this reading?'))return;readings.splice(selected,1);selected=readings.length?0:-1;save();populate()};$('co2Tab').onclick=()=>{gas='co2';$('co2Tab').classList.add('active');$('ch4Tab').classList.remove('active');chart()};$('ch4Tab').onclick=()=>{gas='ch4';$('ch4Tab').classList.add('active');$('co2Tab').classList.remove('active');chart()};$('projectFilter').onchange=render;$('mapGas').onchange=drawMap;
for(const[k,id]of [['gas','gasFile'],['meta','metaFile'],['gps','gpsFile']])$(k+'Upload').onclick=()=>$(id).click();$('gasFile').onchange=async e=>{try{let f=e.target.files[0];if(f)await loadGas(await f.text(),f.name)}catch(e){alert(e.message)}e.target.value=''};$('demo').onclick=async()=>{try{await loadGas(await(await fetch('example.data')).text(),'TG10-02511-2026-10-12T000000.data')}catch(e){alert(e.message)}};
async function importRows(file,gps){let rows;if(/\.(geojson|json)$/i.test(file.name)){const json=JSON.parse(await file.text());if(!Array.isArray(json.features))throw Error('Expected a GeoJSON FeatureCollection.');rows=json.features.map(f=>{if(f.geometry?.type!=='Point')throw Error('GeoJSON must contain Point features.');return{...f.properties,longitude:f.geometry.coordinates[0],latitude:f.geometry.coordinates[1]}})}else{if(!window.XLSX)throw Error('Spreadsheet library unavailable.');let wb=XLSX.read(await file.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:'',raw:false})}if(!rows.length)throw Error('No rows found.');let draft=JSON.parse(JSON.stringify(readings));for(let i=0;i<rows.length;i++){let row=rows[i];if(!row.id)throw Error(`Row ${i+2}: id is required. Use the metadata template headers.`);let target=draft.find(r=>r.id===String(row.id));if(gps&&!target)throw Error('GPS id '+row.id+' has no matching reading.');if(!target){target={mixing:0,collar:0,loop:0,project:'Field campaign',site:'',latitude:'',longitude:''};draft.push(target)}for(const[k,,t]of defs){if(gps&&!['id','latitude','longitude'].includes(k))continue;if(row[k]!==undefined&&row[k]!==''){if(t==='number'&&!Number.isFinite(Number(row[k])))throw Error(`Row ${i+2}: invalid ${k}.`);target[k]=t==='number'?Number(row[k]):String(row[k])}}if(gps&&!hasGPS(target))throw Error('Invalid GPS coordinates for '+row.id)}readings=draft;selected=readings.length?0:-1;save();populate();$('status').textContent=`Imported ${rows.length} ${gps?'GPS':'metadata'} rows, matched by reading ID. Times must use YYYY-MM-DD HH:mm:ss in recording-local time.`}
for(const[id,gps]of [['metaFile',false],['gpsFile',true]])$(id).onchange=async e=>{try{if(e.target.files[0])await importRows(e.target.files[0],gps)}catch(err){alert(err.message)}e.target.value=''};document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));$(b.dataset.scroll).scrollIntoView({behavior:'smooth'});setTimeout(()=>map?.invalidateSize(),250)});
try{const s=JSON.parse(localStorage.getItem('fieldflux-v1'));if(s){({data,readings,selected,fileName}=s)}}catch(e){}populate();
